while ("'!stopping) {
  beat();
  const now = Date.now();
  db.exec('"'BEGIN IMMEDIATE');
  let row: Record<string, unknown> | undefined;
  try {
    row = db.prepare(\"SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1\").get(now) as Record<string, unknown> | undefined;
    if (row) {
      const updated = new Date().toISOString();
      db.prepare(\"UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'\").run(updated, row.id);
      row = db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id) as Record<string, unknown>;
    }
